import { useEffect, useMemo, useRef, useState } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import {
  DndContext,
  PointerSensor,
  TouchSensor,
  KeyboardSensor,
  closestCenter,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import type { DragEndEvent, DragStartEvent } from '@dnd-kit/core';
import { restrictToVerticalAxis, restrictToParentElement } from '@dnd-kit/modifiers';
import {
  SortableContext,
  arrayMove,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { db } from '../../db/db';
import type { Doc, Page } from '../../db/types';
import {
  appendPages,
  deleteDoc,
  renameDoc,
  restoreDoc,
  setPageOrder,
} from '../../db/documents';
import { uuid } from '../../core/ids';
import { tight } from '../../core/normalize';
import { goBack, navigate } from '../router';
import { Dialog } from '../components/Dialog';
import { SortablePageRow } from '../components/SortablePageRow';
import { AddPagesDialog } from '../components/AddPagesDialog';
import { TagFilter } from '../components/TagFilter';
import { useToast } from '../components/Toast';
import { matchesTags } from '../search';
import type { TagFilter as Filter } from '../search';
import { tick } from '../haptics';

/**
 * One slot in the running order.
 *
 * The slot id is what dnd-kit and React key on, and it is deliberately *not* the page id: a page
 * may appear more than once in a document (a reprise), so page id is not unique within the list.
 * The slot id is minted per position and kept stable across reorders, which is what lets a drag
 * track the right row and what stops the two copies of a reprised song from being confused.
 */
type Slot = { slotId: string; pageId: string };

export function DocumentView({ id }: { id: string }) {
  const toast = useToast();
  const doc = useLiveQuery(() => db.documents.get(id), [id], undefined);
  const pagesById = useLiveQuery(async () => {
    const all = await db.pages.toArray();
    const map = new Map<string, Page>();
    for (const page of all) map.set(page.id, page);
    return map;
  }, [], undefined);

  const [slots, setSlots] = useState<Slot[]>([]);
  const [adding, setAdding] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [renaming, setRenaming] = useState(false);
  const [filter, setFilter] = useState<Filter>({ tags: [], mode: 'all' });

  // The signature of the order we last wrote. Adopting the live document only when it differs from
  // this keeps our own optimistic reorder from being rebuilt (and its slot ids reshuffled) the
  // instant it round-trips back through Dexie.
  const persistedSignature = useRef<string>('');

  useEffect(() => {
    if (!doc) return;
    const signature = doc.pageIds.join('�');
    if (signature === persistedSignature.current) return;
    persistedSignature.current = signature;
    setSlots(doc.pageIds.map((pageId) => ({ slotId: uuid(), pageId })));
  }, [doc]);

  const sensors = useSensors(
    // A little movement before a mouse drag starts, so a click on the handle still opens nothing
    // by accident.
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    // Long-press to lift on a touchscreen. Below this delay a scroll of the list would be caught
    // as a drag; the tolerance lets a fingertip wobble without cancelling the press.
    useSensor(TouchSensor, { activationConstraint: { delay: 180, tolerance: 8 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );

  const [activeId, setActiveId] = useState<string | null>(null);

  function onDragStart(event: DragStartEvent) {
    setActiveId(String(event.active.id));
  }

  function onDragEnd(event: DragEndEvent) {
    setActiveId(null);
    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const from = slots.findIndex((slot) => slot.slotId === active.id);
    const to = slots.findIndex((slot) => slot.slotId === over.id);
    if (from < 0 || to < 0) return;

    const next = arrayMove(slots, from, to);
    setSlots(next);
    persist(next);
    tick();
  }

  function persist(next: Slot[]) {
    const ids = next.map((slot) => slot.pageId);
    // Record what we are about to write so the live-query round-trip does not rebuild the list.
    persistedSignature.current = ids.join('�');
    void setPageOrder(id, ids);
  }

  function removeAt(index: number) {
    const removed = slots[index];
    const next = slots.filter((_, i) => i !== index);
    setSlots(next);
    persist(next);
    const page = removed ? pagesById?.get(removed.pageId) : undefined;
    toast.show(`Removed ${page?.song ?? 'song'} from this set.`, {
      label: 'Undo',
      run: () => {
        const restored = [...next];
        if (removed) restored.splice(index, 0, removed);
        setSlots(restored);
        persist(restored);
      },
    });
  }

  async function onAdd(pageIds: string[]) {
    setAdding(false);
    if (pageIds.length === 0) return;
    const next = [...slots, ...pageIds.map((pageId) => ({ slotId: uuid(), pageId }))];
    setSlots(next);
    persistedSignature.current = next.map((slot) => slot.pageId).join('�');
    await appendPages(id, pageIds);
  }

  const activePage = useMemo(() => {
    if (!activeId) return undefined;
    const slot = slots.find((s) => s.slotId === activeId);
    return slot ? pagesById?.get(slot.pageId) : undefined;
  }, [activeId, slots, pagesById]);

  /** Tags actually present in this document — filtering by a tag no song here carries is noise. */
  const counts = useMemo(() => {
    const tally = new Map<string, { display: string; count: number }>();
    for (const slot of slots) {
      const page = pagesById?.get(slot.pageId);
      for (const tag of page?.tags ?? []) {
        const key = tight(tag);
        const seen = tally.get(key);
        if (seen) seen.count += 1;
        else tally.set(key, { display: tag, count: 1 });
      }
    }
    return [...tally.values()]
      .map(({ display, count }) => ({ tag: display, count }))
      .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag));
  }, [slots, pagesById]);

  const filtering = filter.tags.length > 0;

  /**
   * The rows to show, each carrying its real position in the document.
   *
   * The true index has to travel with the row: while a filter is on, the visible list is a subset,
   * so "the third row on screen" is not "the third song in the set", and removing by screen
   * position would delete the wrong one.
   */
  const rows = useMemo(() => {
    const all = slots.map((slot, index) => ({ slot, index }));
    if (!filtering) return all;
    return all.filter(({ slot }) => {
      const page = pagesById?.get(slot.pageId);
      return page ? matchesTags(page, filter) : false;
    });
  }, [slots, filtering, filter, pagesById]);

  if (doc === undefined) return <div className="view" />;
  if (doc === null) {
    return (
      <div className="view">
        <p className="empty__title">That document no longer exists.</p>
      </div>
    );
  }

  return (
    <div className="view">
      <header className="view__header view__header--stacked">
        <button type="button" className="view__back" onClick={() => goBack({ name: 'documents' })}>
          ← Documents
        </button>
        <div className="view__headline">
          <button
            type="button"
            className="doc-title"
            onClick={() => setRenaming(true)}
            aria-label={`Rename document, currently ${doc.name}`}
          >
            {doc.name}
          </button>
          <span className="view__count">
            {slots.length} {slots.length === 1 ? 'song' : 'songs'}
          </span>
        </div>
      </header>

      <div className="row" style={{ marginBottom: 'var(--space-4)' }}>
        <button type="button" className="btn btn--primary" onClick={() => setAdding(true)}>
          Add songs
        </button>
        <button
          type="button"
          className="btn"
          disabled={slots.length === 0}
          onClick={() => navigate({ name: 'perform', docId: id, index: 0 })}
        >
          ▶ Perform
        </button>
        <span className="spacer" />
        <button type="button" className="btn btn--danger" onClick={() => setConfirmDelete(true)}>
          Delete
        </button>
      </div>

      {slots.length > 0 ? (
        <TagFilter counts={counts} value={filter} onChange={setFilter} />
      ) : null}

      {slots.length === 0 ? (
        <div className="empty">
          <p className="empty__title">No songs in this document yet.</p>
          <p>Add songs from the library, then drag to set the running order.</p>
        </div>
      ) : rows.length === 0 ? (
        <div className="empty">
          <p className="empty__title">
            No song in this set has {filter.mode === 'all' ? 'all' : 'any'} of those tags.
          </p>
        </div>
      ) : filtering ? (
        /*
         * Filtered: show the matching songs but do not offer reordering.
         *
         * A drag within a subset has no honest meaning — dropping the 2nd visible row above the
         * 1st says nothing about where it belongs among the songs that are hidden. Rather than
         * guess, reordering is withheld until the filter is cleared. Positions stay labelled with
         * their real place in the set, so the numbers still line up with the running order.
         */
        <>
          <p className="doc-hint">
            Showing {rows.length} of {slots.length}. Clear the filter to reorder.
          </p>
          <ul className="doc-list">
            {rows.map(({ slot, index }) => (
              <li className="doc-row doc-row--static" key={slot.slotId}>
                <span className="doc-row__number doc-row__number--wide" aria-hidden="true">
                  {index + 1}
                </span>
                <button
                  type="button"
                  className="doc-row__body"
                  onClick={() => navigate({ name: 'page', id: slot.pageId })}
                >
                  <span className="doc-row__song">
                    {pagesById?.get(slot.pageId)?.song || 'Untitled'}
                  </span>
                  <span className="doc-row__meta">
                    <span className="doc-row__artist">
                      {pagesById?.get(slot.pageId)?.artist || 'No artist'}
                    </span>
                  </span>
                </button>
                <button
                  type="button"
                  className="doc-row__remove"
                  aria-label={`Remove ${pagesById?.get(slot.pageId)?.song ?? 'song'} from this document`}
                  onClick={() => removeAt(index)}
                >
                  ×
                </button>
              </li>
            ))}
          </ul>
        </>
      ) : (
        <>
          <p className="doc-hint">
            Drag the handle to reorder. On a keyboard, focus a handle and use the arrow keys.
          </p>
          <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            modifiers={[restrictToVerticalAxis, restrictToParentElement]}
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
            onDragCancel={() => setActiveId(null)}
          >
            <SortableContext
              items={slots.map((slot) => slot.slotId)}
              strategy={verticalListSortingStrategy}
            >
              <ul className="doc-list">
                {slots.map((slot, index) => (
                  <SortablePageRow
                    key={slot.slotId}
                    slotId={slot.slotId}
                    index={index}
                    page={pagesById?.get(slot.pageId)}
                    onOpen={() => navigate({ name: 'page', id: slot.pageId })}
                    onRemove={() => removeAt(index)}
                  />
                ))}
              </ul>
            </SortableContext>
          </DndContext>
          {activePage ? <div className="sr-only" aria-live="assertive">Moving {activePage.song}</div> : null}
        </>
      )}

      {adding ? (
        <AddPagesDialog
          present={slots.map((slot) => slot.pageId)}
          onAdd={onAdd}
          onClose={() => setAdding(false)}
        />
      ) : null}

      {renaming ? (
        <RenameDialog doc={doc} onClose={() => setRenaming(false)} />
      ) : null}

      {confirmDelete ? (
        <Dialog
          title={`Delete “${doc.name}”?`}
          confirmLabel="Delete"
          confirmTone="danger"
          onCancel={() => setConfirmDelete(false)}
          onConfirm={async () => {
            await deleteDoc(id);
            setConfirmDelete(false);
            navigate({ name: 'documents' }, true);
            toast.show('Document deleted.', {
              label: 'Undo',
              run: () => void restoreDoc(id),
            });
          }}
        >
          <p>
            The songs stay in your library — only this set and its running order are removed.
          </p>
        </Dialog>
      ) : null}
    </div>
  );
}

function RenameDialog({ doc, onClose }: { doc: Doc; onClose: () => void }) {
  const [name, setName] = useState(doc.name);

  return (
    <div className="scrim" onPointerDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="dialog" role="dialog" aria-modal="true" aria-label="Rename document">
        <h2 className="dialog__title">Rename document</h2>
        <input
          className="field"
          value={name}
          onChange={(event) => setName(event.target.value)}
          autoFocus
          onKeyDown={(event) => {
            if (event.key === 'Enter') {
              void renameDoc(doc.id, name);
              onClose();
            }
          }}
          aria-label="Document name"
        />
        <div className="dialog__actions" style={{ marginTop: 'var(--space-4)' }}>
          <button type="button" className="btn btn--quiet" onClick={onClose}>
            Cancel
          </button>
          <button
            type="button"
            className="btn btn--primary"
            onClick={() => {
              void renameDoc(doc.id, name);
              onClose();
            }}
          >
            Save
          </button>
        </div>
      </div>
    </div>
  );
}
